sp_widget.client_script:
api.controller = function($timeout) {

    var c = this;


    function renderQR() {

        $timeout(function() {

            angular.forEach(
                c.data.tickets || [],
                function(ticket) {

                    if (
                        ticket.status == 'generated' &&
                        ticket.qr_data
                    ) {

                        var element =
                            document.getElementById(
                                'qr-' + ticket.sys_id
                            );

                        if (!element) {
                            return;
                        }

                        if (
                            typeof QRCode === 'undefined'
                        ) {

                            console.error(
                                'QRCode.js library is not loaded.'
                            );

                            return;
                        }

                        element.innerHTML = '';

                        new QRCode(
                            element,
                            {
                                text:
                                    ticket.qr_data,

                                width:
                                    160,

                                height:
                                    160
                            }
                        );
                    }
                }
            );

        }, 500);
    }


    renderQR();


    // ---------------------------------
    // Cancel Ticket
    // ---------------------------------

    c.cancelTicket =
        function(ticket) {

            var reason =
                window.prompt(
                    'Enter cancellation reason:',
                    ''
                );

            // User clicked Cancel on popup
            if (reason === null) {
                return;
            }

            c.server.get({

                action:
                    'cancel',

                sys_id:
                    ticket.sys_id,

                reason:
                    reason

            }).then(function(response) {

                c.data =
                    response.data;

                renderQR();

            });
        };
};

sp_widget.css:
.metro-tickets {
    max-width: 1000px;
    margin: 35px auto;
    padding: 20px;
}


.page-heading {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 30px;
}


.page-heading h2 {
    margin: 0;
}


.page-subtitle {
    margin-top: 7px;
    color: #666666;
}


.ticket-card {
    background: #ffffff;
    border: 1px solid #dddddd;
    border-radius: 12px;
    padding: 24px;
    margin-bottom: 24px;
    box-shadow: 0 3px 12px rgba(0, 0, 0, 0.08);
}


.ticket-header {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    margin-bottom: 22px;
}


.ticket-header h3 {
    margin-top: 0;
    margin-bottom: 8px;
}


.route {
    font-size: 18px;
    font-weight: 500;
}


.route-arrow {
    padding: 0 10px;
}


.ticket-details {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 16px 30px;
}


.ticket-details div {
    display: flex;
    flex-direction: column;
}


.ticket-details b {
    margin-bottom: 5px;
    color: #555555;
}


.status-badge {
    padding: 7px 14px;
    border-radius: 20px;
    font-size: 13px;
    font-weight: 600;
    background: #eeeeee;
}


.status-pending {
    background: #fff3cd;
}


.status-approved {
    background: #dbeafe;
}


.status-generated {
    background: #d1fae5;
}


.status-rejected {
    background: #fee2e2;
}


.status-cancelled {
    background: #e5e7eb;
}


.qr-section {
    margin-top: 28px;
    padding-top: 22px;
    border-top: 1px solid #eeeeee;
    text-align: center;
}


.qr-section h4 {
    margin-bottom: 16px;
}


.qr-code {
    display: inline-block;
    background: #ffffff;
    padding: 12px;
    border: 1px solid #eeeeee;
    border-radius: 8px;
}


.qr-code img,
.qr-code canvas {
    display: block;
    margin: 0 auto;
}


.qr-ticket-number {
    margin-top: 12px;
    font-weight: 600;
    font-size: 15px;
}


.qr-help {
    margin-top: 5px;
    color: #777777;
    font-size: 13px;
}


.cancelled-info {
    margin-top: 22px;
    padding: 15px;
    background: #f5f5f5;
    border-radius: 8px;
}


.cancelled-info div {
    margin-bottom: 6px;
}


.empty-message {
    padding: 50px;
    text-align: center;
    background: #ffffff;
    border: 1px solid #dddddd;
    border-radius: 10px;
}


@media (max-width: 600px) {

    .page-heading {
        flex-direction: column;
        align-items: flex-start;
        gap: 15px;
    }


    .ticket-header {
        flex-direction: column;
        gap: 15px;
    }


    .ticket-details {
        grid-template-columns: 1fr;
    }


    .metro-tickets {
        padding: 12px;
    }
}

.cancel-action {
    margin-top: 22px;
    text-align: right;
}

sp_widget.script:
(function() {

    data.tickets = [];
    data.message = '';
    data.error = '';

    var today = new GlideDate().getValue();


    // ---------------------------------
    // Cancel Ticket
    // ---------------------------------
    if (
        input &&
        input.action == 'cancel'
    ) {

        var booking =
            new GlideRecordSecure(
                'x_1958892_metro_0_metro_booking'
            );

        if (!booking.get(input.sys_id)) {

            data.error =
                'Booking not found.';

        } else if (
            booking.getValue('requested_for') !=
            gs.getUserID()
        ) {

            data.error =
                'You are not authorized to cancel this ticket.';

        } else if (
            booking.getValue('metro_status') !=
            'generated'
        ) {

            data.error =
                'Only generated tickets can be cancelled.';

        } else if (
            booking.getValue('travel_date') < today
        ) {

            data.error =
                'Past tickets cannot be cancelled.';

        } else {

            var reason =
                input.reason || '';

            if (!reason) {
                reason =
                    'Cancelled by passenger';
            }

            booking.setValue(
                'metro_status',
                'cancelled'
            );

            booking.setValue(
                'cancellation_reason',
                reason
            );

            booking.update();

            data.message =
                'Ticket cancelled successfully.';
        }
    }


    // ---------------------------------
    // Load Current User Tickets
    // ---------------------------------

    var gr =
        new GlideRecordSecure(
            'x_1958892_metro_0_metro_booking'
        );

    gr.addQuery(
        'requested_for',
        gs.getUserID()
    );

    gr.orderByDesc(
        'sys_created_on'
    );

    gr.query();


    while (gr.next()) {

        var travelDate =
            gr.getValue('travel_date');

        data.tickets.push({

            sys_id:
                gr.getUniqueValue(),

            number:
                gr.getValue('number'),

            ticket_number:
                gr.getValue('ticket_number'),

            source:
                gr.getDisplayValue('source_station'),

            destination:
                gr.getDisplayValue('destination_station'),

            travel_date:
                travelDate,

            journey_type:
                gr.getDisplayValue('journey_type'),

            passenger_count:
                gr.getValue('passenger_count'),

            distance_km:
                gr.getValue('distance_km'),

            duration_minutes:
                gr.getValue('duration_minutes'),

            base_fare:
                gr.getValue('base_fare'),

            total_fare:
                gr.getValue('total_fare'),

            status:
                gr.getValue('metro_status'),

            status_display:
                gr.getDisplayValue('metro_status'),

            generated_at:
                gr.getDisplayValue('generated_at'),

            refund_amount:
                gr.getValue('refund_amount'),

            cancellation_reason:
                gr.getValue('cancellation_reason'),

            qr_data:
                gr.getValue('qr_data'),

            can_cancel:
                gr.getValue('metro_status') ==
                    'generated' &&
                travelDate >= today
        });
    }

})();
